/**
 * Componente oficial de Logotipo OptiFlow: Isotipo en espiral + Tipografía institucional.
 */
export const Logo: React.FC<LogoProps> = ({
  className = '',
  isotypeClassName = 'w-11 h-11',
  textClassName = '',
  size = 'lg',
  variant = 'light',
  showText = true,
  isotypeOnly = false
}) => {
  const sizeMap: Record<string, string> = {
    sm: 'text-lg',
    md: 'text-2xl',
    lg: 'text-3xl',
    xl: 'text-4xl'
  }

  const textSize = sizeMap[size] || 'text-3xl'

  return (
    <div className={`flex items-center gap-3 select-none ${className}`}>
      <OptiFlowIsotype className={isotypeClassName} />
      {showText && !isotypeOnly && (
        <span
          className={`tracking-tight font-sans leading-none flex items-center ${textSize} ${textClassName}`}
        >
          <span
            className={
              variant === 'dark'
                ? 'font-extrabold text-white'
                : 'font-extrabold text-slate-800'
            }
          >
            Opti
          </span>
          <span className="font-semibold text-orange-500">Flow</span>
        </span>
      )}
    </div>
  )
}

export default Logo
